WHERE t.del_flag = '0'
AND t.schedule_no LIKE CONCAT('%', #{bo.scheduleNo}, '%')
AND t.store_id = #{bo.storeId}
AND t.coach_id = #{bo.coachId}
AND t.course_id = #{bo.courseId}
AND t.schedule_status = #{bo.scheduleStatus}
AND t.schedule_mode = #{bo.scheduleMode}
AND t.schedule_date >= #{bo.scheduleDateStart}
AND t.schedule_date <= #{bo.scheduleDateEnd}
ORDER BY t.schedule_date DESC, t.start_time DESC, t.schedule_id DESC



